-- ============================================================================
-- H1: Safety Performance Statistics & KPIs joins the catalogue, the FIRST
-- course of the HSE module.
--
-- Catalogue row (module 'hse'; path_order 61, directly above the Assurance
-- module's compliance at 60 and riskchange at 59; prereq_slug NULL, the
-- carried-over answer "no hard prerequisite inside a module"; school left at
-- its default, as every Facilities, Economics and Assurance course leaves it,
-- so the fees are the published school-level rows) plus the three capstones
-- and their eighteen graded fields, generated by
-- tools/course-waves/safetystats/gen_course.py from the ENGINE'S OWN RUN
-- (h1_capstone.mjs through the vendored engines/hse/safetyStats.js), which it
-- refuses to write unless fields.json carries exactly that run's values and
-- the tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/safetystats, because the 78
-- lessons, the teaching lab (safetystatsLab.js) and its three explorer panels
-- ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A safety rate is a count divided by exposure
-- hours on a base somebody chose, so the course teaches what the rate is
-- (Associate), how sure it is (Professional) and whether anything is changing
-- (Expert), and grades each tier on its own question with numbers the engine
-- returns.
--
-- THE ENGINE. engines/hse/safetyStats.js, vendored sha-identical with
-- petrolord-engines 980199e. It imports nothing. The base is required, the
-- severity rate has no single standard, the API RP 754 tier is an input,
-- rates are summed then divided, the two-sided p-value is the CENTRAL one and
-- a signal lies strictly outside its limits.
--
-- WHAT IS GRADED. OKRIKA (Associate) grades six rates on stated bases and one
-- rolling window; BONNY (Professional) grades the Garwood limits, a zero-event
-- limit, a rate-ratio interval and the central p-value; FORCADOS (Expert)
-- grades a u-chart's centre and two limits, a revised centre and two
-- before-and-after p-values that disagree because of one month. Every value
-- is a return value of the engine, and every prompt is rendered from the
-- inputs the engine was run on.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, at each
-- field's own shipped tolerance: 0 collisions, and 0 pairwise. No prompt
-- states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('safetystats', 'Safety Performance Statistics & KPIs', 'hse', 61, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'safetystats', 'beginner', 'associate',
  'OKRIKA, an export terminal''s annual safety report and fourteen months of recordable cases',
  'What the rate is, on the base the report names',
  'OKRIKA, an export terminal. Its annual safety report for the calendar year counts company employees and contractors separately. Employees worked 1846220 hours and had 5 recordable cases. Contractors worked 3127655 hours and had 11 recordable cases. Across both workforces the year had 4 lost time injuries, 1 fatality, 187 days lost, 3 Tier 1 process safety events and 7 Tier 2 process safety events, each event classified against API RP 754 before it reached you. The fatality is already counted once among the recordable cases and once among the lost time injuries, so it is added to neither count again. The terminal''s combined recordable cases and hours for fourteen months follow. Months 1 to 12 are the calendar year above, and months 13 and 14 are the first two months of the next year: month 1, 1 recordable case in 452115 hours; month 2, 2 in 439760; month 3, 0 in 468930; month 4, 1 in 27450; month 5, 3 in 446205; month 6, 1 in 461880; month 7, 0 in 455330; month 8, 2 in 448615; month 9, 1 in 470470; month 10, 2 in 441905; month 11, 1 in 458240; month 12, 2 in 402975; month 13, 1 in 449820; month 14, 1 in 36180. Report six values, each on the base named: the combined recordable rate of the two workforces per 200,000 hours; the combined lost time injury rate per 1,000,000 hours; the observed FAR; the severity rate per 200,000 hours, with the days lost as counted and no time charges added; the Tier 1 process safety event rate per 200,000 hours; and the rolling twelve-month recordable rate per 200,000 hours for the window that ends at month 14. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','okrika_combined_trir_per_200k', 'label','The combined recordable rate of employees and contractors per 200,000 hours', 'unit','per 200,000 hours', 'expected',0.6433615641728029, 'tol',5e-07),
    jsonb_build_object('key','okrika_combined_ltir_per_1m', 'label','The combined lost time injury rate per 1,000,000 hours', 'unit','per 1,000,000 hours', 'expected',0.8042019552160036, 'tol',5e-07),
    jsonb_build_object('key','okrika_far_per_100m', 'label','The observed FAR, fatalities per 100,000,000 hours', 'unit','per 100,000,000 hours', 'expected',20.10504888040009, 'tol',5e-07),
    jsonb_build_object('key','okrika_severity_rate_per_200k', 'label','The severity rate, days lost per 200,000 hours', 'unit','days per 200,000 hours', 'expected',7.519288281269634, 'tol',5e-07),
    jsonb_build_object('key','okrika_tier1_pse_rate_per_200k', 'label','The Tier 1 process safety event rate per 200,000 hours', 'unit','per 200,000 hours', 'expected',0.12063029328240055, 'tol',5e-07),
    jsonb_build_object('key','okrika_rolling12_trir_month14_per_200k', 'label','The rolling twelve-month recordable rate for the window that ends at month 14', 'unit','per 200,000 hours', 'expected',0.6567425569176882, 'tol',5e-07)
  )
),
(
  'safetystats', 'intermediate', 'professional',
  'BONNY, two contractor crews on one scope and a small crew with no recordable case',
  'How sure each rate is, and whether the two crews differ',
  'BONNY, a terminal expansion where two contractor crews work the same scope and a small crew works beside them. Crew Alpha recorded 9 recordable cases in 612340 hours. Crew Beta recorded 7 recordable cases in 1406775 hours. The small crew recorded 0 recordable cases in 83560 hours. Treat each count as a draw from a Poisson count model, and work at 95 percent confidence throughout. Report six values: the lower limit of the confidence interval on Alpha''s recordable rate per 200,000 hours; the upper limit of that interval; the upper limit of the confidence interval on the small crew''s rate per 200,000 hours; the lower limit of the confidence interval on the rate ratio, Alpha''s rate over Beta''s; the upper limit of that interval; and the two-sided p-value the engine reports for Alpha against Beta. The limits per 200,000 hours, the ratio limits as plain numbers and the p-value as a probability, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','bonny_alpha_trir_lower95_per_200k', 'label','The lower limit of the 95 percent confidence interval on Alpha''s recordable rate', 'unit','per 200,000 hours', 'expected',1.3441464210661842, 'tol',5e-07),
    jsonb_build_object('key','bonny_alpha_trir_upper95_per_200k', 'label','The upper limit of the 95 percent confidence interval on Alpha''s recordable rate', 'unit','per 200,000 hours', 'expected',5.580169007877703, 'tol',5e-07),
    jsonb_build_object('key','bonny_crew_zero_event_upper95_per_200k', 'label','The upper limit of the 95 percent confidence interval on the small crew''s rate, with no recordable case', 'unit','per 200,000 hours', 'expected',8.829295007453174, 'tol',5e-07),
    jsonb_build_object('key','bonny_rate_ratio_lower95', 'label','The lower limit of the 95 percent confidence interval on the rate ratio, Alpha''s rate over Beta''s', 'unit','ratio', 'expected',0.9788650276137694, 'tol',5e-07),
    jsonb_build_object('key','bonny_rate_ratio_upper95', 'label','The upper limit of the 95 percent confidence interval on the rate ratio, Alpha''s rate over Beta''s', 'unit','ratio', 'expected',9.332895636622686, 'tol',5e-07),
    jsonb_build_object('key','bonny_compare_p_value', 'label','The two-sided p-value the engine reports for Alpha against Beta', 'unit','probability', 'expected',0.05508741246272278, 'tol',5e-07)
  )
),
(
  'safetystats', 'advanced', 'expert',
  'FORCADOS, a year of monthly recordable cases on a u-chart around an intervention',
  'Whether anything is changing, and what one month does to the answer',
  'FORCADOS, a producing field, charted month by month on a u-chart of recordable cases per 200,000 hours. Month 7 carried a turnaround and month 9 a shutdown, and an intervention went in at the start of month 7. The twelve months, recordable cases then hours: month 1, 14 recordable cases in 736410 hours; month 2, 11 in 702885; month 3, 17 in 781260; month 4, 9 in 544370; month 5, 13 in 719935; month 6, 38 in 902640; month 7, 21 in 1386215; month 8, 12 in 748120; month 9, 2 in 118460; month 10, 13 in 731055; month 11, 10 in 694830; month 12, 11 in 752390. The cause of any month the chart signals on has been investigated and found, and it is one the intervention did not produce. Compare the two halves at 95 percent confidence. Report six values: the centre line; the upper control limit at month 9; the lower control limit at month 7; the centre line recomputed without the month the chart signals on; the two-sided p-value the engine reports for months 7 to 12 against months 1 to 6; and the same p-value with the signalling month left out of months 1 to 6. The centre lines and limits per 200,000 hours and the p-values as probabilities, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','forcados_centre_per_200k', 'label','The u-chart centre line', 'unit','per 200,000 hours', 'expected',3.878179795590441, 'tol',5e-07),
    jsonb_build_object('key','forcados_ucl_month09_per_200k', 'label','The upper control limit at month 9', 'unit','per 200,000 hours', 'expected',11.55469930741927, 'tol',5e-07),
    jsonb_build_object('key','forcados_lcl_month07_per_200k', 'label','The lower control limit at month 7', 'unit','per 200,000 hours', 'expected',1.634117414998765, 'tol',5e-07),
    jsonb_build_object('key','forcados_revised_centre_per_200k', 'label','The centre line recomputed without the month the chart signals on', 'unit','per 200,000 hours', 'expected',3.3603126859383545, 'tol',5e-07),
    jsonb_build_object('key','forcados_before_after_p_value', 'label','The two-sided p-value for months 7 to 12 against months 1 to 6', 'unit','probability', 'expected',0.011814431372499143, 'tol',5e-07),
    jsonb_build_object('key','forcados_before_after_p_value_without_month06', 'label','The same p-value with the signalling month left out of months 1 to 6', 'unit','probability', 'expected',0.3869280005870388, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
